import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.Drp2S_UI.js";const p=JSON.parse('{"title":"T14 原生控件、列表与装饰","description":"","frontmatter":{},"headers":[],"relativePath":"guide/native-chrome-layout.md","filePath":"guide/native-chrome-layout.md","lastUpdated":1792653875000}'),l={name:"guide/native-chrome-layout.md"};function r(d,e,c,n,s,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="t14-原生控件、列表与装饰" tabindex="-1">T14 原生控件、列表与装饰 <a class="header-anchor" href="#t14-原生控件、列表与装饰" aria-label="Permalink to &quot;T14 原生控件、列表与装饰&quot;">​</a></h1><p>控件、标签和列表的文字统一交给 HarfBuzz。几何在换行前确定，宿主仅投影到现有 绘制与交互入口，后续 T17/T19 继续迁移这些消费者。</p><h2 id="控件与标签" tabindex="-1">控件与标签 <a class="header-anchor" href="#控件与标签" aria-label="Permalink to &quot;控件与标签&quot;">​</a></h2><ul><li><code>ControlLayout</code> 使用 HB 的实际宽度计算 <code>minWidth</code> 差额，生成临时 <code>controlSpace</code> 内联对象。补白有真实源元素锚点，不创建或修改持久化内容。长补白可跨行； VALUE_START 的续行缩进参与可用行宽计算，CENTER/RIGHT 在控件内分配补白。</li><li>移除 <code>applyEngineRowsMinWidth</code>、<code>applyEngineRowsMetrics</code> 和 Draw 中的续行平移。 原生节点、字形、光标和兼容行共享相同几何。重复源元素跨行时使用独立投影， 避免后行覆盖前行的补白盒。</li><li>标签保留原文字形簇和阿拉伯文连写。原生标签盒包含四边 padding，整块参与换行， 行高预留 padding；背景盒不包含段落 rowMargin。</li><li>空行仍属于原生渲染入口；隐藏控件折叠宽高，不分配可见补白。</li><li>normalizer 与序列化过滤历史 <code>isControlMinWidthPlaceholder</code>，语义 PLACEHOLDER 仍正常保留，用于空值展示、赋值与缺字定位。</li></ul><h2 id="列表与装饰" tabindex="-1">列表与装饰 <a class="header-anchor" href="#列表与装饰" aria-label="Permalink to &quot;列表与装饰&quot;">​</a></h2><ul><li><code>collectListMarkers</code> 按 listId 延续序号，listWrap 不增加编号，嵌套列表保留独立身份。 标记按实际字体、字重、样式和真实编号测量，避免多位编号宽度不足与重复缩放。</li><li>列表标记用 HB 字形轮廓绘制，不调用 Canvas <code>measureText</code> 或 <code>fillText</code>。 原生 <code>TextLine.marker</code> 保存源锚点与标记几何，列表 gutter 与层级缩进进入段落宽度； RTL 嵌套标记不再重复扣除层级缩进而覆盖内容。</li><li>Hyperlink/Date/控件 chrome 使用正文原生字形。标签背景、控件背景与边框、 高亮、下划线、删除线和留痕使用投影几何；原生删除线、留痕不测量旧基准文字。 编辑、复选框标签切换与只读规则沿用现有命令和事件逻辑。</li></ul><h2 id="缺字定位" tabindex="-1">缺字定位 <a class="header-anchor" href="#缺字定位" aria-label="Permalink to &quot;缺字定位&quot;">​</a></h2><p>覆盖扫描包含实际控件值、占位文字与生成的列表标记，不扫描排版补白。 页面详情提供“定位缺字”按钮。按源 nodeId 重新查找当前元素，设置正文/页眉/页脚 及嵌套表格路径，再选择源元素；已删除的源不会根据过期下标误选其他内容。 缺字盒也使用实际元素源标识，保持与覆盖报告一致。</p><h2 id="定向验证" tabindex="-1">定向验证 <a class="header-anchor" href="#定向验证" aria-label="Permalink to &quot;定向验证&quot;">​</a></h2><p>本次通过 10 个 Vitest 文件（69 项）及 12 个 Cypress 场景。类型检查、编辑文件 ESLint、ESM 构建及包消费者检查通过。</p><ul><li>Vitest：原生控件、段落、签名、Label/Date、对象、表格、布局提取及字体诊断/覆盖。 新增缩放 0.75/1/2、LTR/RTL、对齐、续行、跨行补白、标签连写/原子换行、 9/99/100 编号、续号、隐藏控件和表格内在宽度检查。</li><li>Cypress <code>native-chrome.cy.ts</code>：LTR/RTL 各 6 个场景，覆盖赋值/清空/覆盖开关、 长值换行、复选框标签点击、只读、标签与高亮像素、列表几何、值/占位文字/ 表格控件缺字定位与打印。测试主动禁止旧文字粒子的测量及 record。</li><li>类型、编辑文件 ESLint、ESM 构建与包消费者检查。</li></ul><p>全量回归按约定暂缓。显式 legacy 分支及其旧循环将在 T20 统一删除； 分页/分栏/环绕接线仍属于 T15，本任务未提前宣称完成。</p>',12)])])}const T=a(l,[["render",r]]);export{p as __pageData,T as default};
